package com.vms.vendorcontractmanagement.service; import com.vms.vendorcontractmanagement.dto.VendorDtos.*; import com.vms.vendorcontractmanagement.entity.*; import com.vms.vendorcontractmanagement.exception.*; import com.vms.vendorcontractmanagement.repository.*; import lombok.*; import org.springframework.data.domain.*; import org.springframework.http.*; import org.springframework.stereotype.*; import org.springframework.transaction.annotation.*; import java.util.*;
@Service @RequiredArgsConstructor public class VendorService {final VendorRepository vendors;final UserRepository users;final ContractRepository contracts;final AuditService audit; @Transactional(readOnly=true) public Page<Response> list(String s,String cat,String stat,Pageable p){return vendors.search(blank(s),blank(cat),blank(stat),p).map(this::dto);} public Response get(Long id){return dto(find(id));} @Transactional public Response create(Request r){if(vendors.existsByVendorCode(r.vendorCode()))throw new ApiException(HttpStatus.CONFLICT,"Vendor code already exists");Vendor v=apply(new Vendor(),r);vendors.save(v);audit.log("CREATE","VENDOR",v.getId(),null,v.getVendorCode());return dto(v);} @Transactional public Response update(Long id,Request r){Vendor v=find(id);String old=v.getVendorName();apply(v,r);audit.log("UPDATE","VENDOR",id,old,v.getVendorName());return dto(v);} @Transactional public void delete(Long id){if(contracts.existsByVendorIdAndStatus(id,"ACTIVE"))throw new ApiException(HttpStatus.BAD_REQUEST,"Vendor has active contracts");Vendor v=find(id);vendors.delete(v);audit.log("DELETE","VENDOR",id,v.getVendorCode(),null);} @Transactional public Response status(Long id,String status){Vendor v=find(id);v.setStatus(status.equalsIgnoreCase("ACTIVE")?"INACTIVE":"ACTIVE");return dto(v);} Vendor find(Long id){return vendors.findById(id).orElseThrow(()->new ApiException(HttpStatus.NOT_FOUND,"Vendor not found"));} Vendor apply(Vendor v,Request r){v.setVendorCode(r.vendorCode());v.setVendorName(r.vendorName());v.setCategory(r.category());v.setContactEmail(r.contactEmail());v.setPhone(r.phone());v.setCountry(r.country());if(r.status()!=null)v.setStatus(r.status());if(r.ownerUserId()!=null)v.setOwner(users.findById(r.ownerUserId()).orElseThrow(()->new ApiException(HttpStatus.BAD_REQUEST,"Owner not found")));return v;} Response dto(Vendor v){return new Response(v.getId(),v.getVendorCode(),v.getVendorName(),v.getCategory(),v.getContactEmail(),v.getPhone(),v.getCountry(),v.getStatus(),v.getOwner()==null?null:v.getOwner().getId(),v.getOwner()==null?null:v.getOwner().getFullName(),v.getDepartments().stream().map(Department::getDepartmentName).collect(java.util.stream.Collectors.toSet()));} String blank(String s){return s==null||s.isBlank()?null:s;} }
